def amicable_numbers_sum(n):
    """Return the sum of all amicable numbers from 1 to n.

    Two numbers a and b are amicable if the sum of the proper divisors
    of a equals b, the sum of the proper divisors of b equals a, and a != b.
    """
    if n < 2:
        return 0

    # Sieve: d[x] = sum of proper divisors of x
    d = [0] * (n + 1)
    for i in range(1, n // 2 + 1):
        for j in range(2 * i, n + 1, i):
            d[j] += i

    total = 0
    for a in range(2, n + 1):
        b = d[a]
        if b != a and 1 <= b <= n and d[b] == a:
            total += a
    return total
```

