def max_sub_array_sum_repeated(a, n, k):
    """
    Largest sum of a contiguous subarray in the array formed by
    repeating the given array a (of length n) k times.
    """
    def kadane(arr):
        max_ending = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending = max(x, max_ending + x)
            if max_ending > max_so_far:
                max_so_far = max_ending
        return max_so_far

    # Best subarray contained within a single copy.
    max_single = kadane(a)

    if k == 1:
        return max_single

    total = sum(a)

    # Maximum sum of any prefix of a.
    max_prefix = float('-inf')
    curr = 0
    for x in a:
        curr += x
        if curr > max_prefix:
            max_prefix = curr

    # Maximum sum of any suffix of a.
    max_suffix = float('-inf')
    curr = 0
    for x in reversed(a):
        curr += x
        if curr > max_suffix:
            max_suffix = curr

    if total > 0:
        # Best spans copies: suffix of first, k-2 whole copies, prefix of last.
        return max(max_single, max_suffix + (k - 2) * total + max_prefix)
    else:
        # Whole extra copies don't help; best spanning case uses two copies.
        return max(max_single, max_suffix + max_prefix)
```

