def max_sub_array_sum(arr, n):
    max_so_far = float('-inf')
    max_ending_here = 0
    for i in range(n):
        max_ending_here += arr[i]
        if max_ending_here > max_so_far:
            max_so_far = max_ending_here
        if max_ending_here < 0:
            max_ending_here = 0
