def find_kth(arr1, arr2, k):
    # k is 1-indexed: the kth element of the merged sorted arrays
    # Ensure arr1 is the shorter array
    if len(arr1) > len(arr2):
        return find_kth(arr2, arr1, k)

    m, n = len(arr1), len(arr2)

    # Binary search on the number of elements taken from arr1
    low = max(0, k - n)
    high = min(k, m)

    while low <= high:
        i = (low + high) // 2  # count taken from arr1
        j = k - i              # count taken from arr2

        left1 = arr1[i - 1] if i > 0 else float('-inf')
        right1 = arr1[i] if i < m else float('inf')
        left2 = arr2[j - 1] if j > 0 else float('-inf')
        right2 = arr2[j] if j < n else float('inf')

        if left1 <= right2 and left2 <= right1:
            return max(left1, left2)
        elif left1 > right2:
            high = i - 1
        else:
            low = i + 1

    return None
